P=/home/siegfriedneto/.claude/plugins/cache/siegard-generator/siegard/5.7.2 && D=siegard-delivery/succession-reaffirms-same-target && W=siegard-work/succession-reaffirms-same-target && python3 -I /tmp/tools/save_return2.py a32cc22dc6b364dc8 /tmp/proof-return7.yaml && mkdir -p $D/proof/succession-reaffirms-same-target && IMPL=$(sha256sum $D/implementation/succession-reaffirms-same-target/reaffirm-same-target-succession.md | cut -d' ' -f1) IMPL=$IMPL python3 -I - <<'EOF'
import yaml,os
r=yaml.safe_load(open('/tmp/proof-return7.yaml'))
rec={'target':'backend','implementation':'sha256:'+os.environ['IMPL'],
'standard':{'at':'../standards/backend-node-service.yaml','pin':'sha256:8c38c4f11796188276d89c2c7ed1710a4eed05f701034f22c68af0a554142c77'},
'run':'run/succession-reaffirms-same-target-reaffirm-same-target-succession-suite'}
for k in ('title','summary','tests','files','not_applicable','untested','divergences'):
    if k in r: rec[k]=r[k]
for t in rec['tests']:
    for k in ('name','proves','fails_when'): t[k]=' '.join(str(t[k]).split())
for x in rec['files']: x['effect']=' '.join(str(x['effect']).split())
body="\n## What it is\nTests over consolidateLink and consolidateAttribute, run against the store stand-in, prove that a succession proposal repeating the current target or value is answered consolidated on the held assertion, and prove the neighboring rules the change must not move.\nTwo existing tests that asserted the old behavior were rewritten whole and are named under files.\n\n## Notes\nNo earlier suite run failed before this one passed.\nThe test author recorded no disagreement with the implementation.\nThe divergence names the comments that graph-consolidation.spec.ts still holds from earlier deliveries; this delivery removed only the block of the test it rewrote.\n"
open('siegard-delivery/succession-reaffirms-same-target/proof/succession-reaffirms-same-target/reaffirm-same-target-succession.md','w').write('---\n'+yaml.safe_dump(rec,sort_keys=False,allow_unicode=True,width=10000)+'---\n'+body)
print(len(rec['tests']))
EOF
python3 -B $P/bin/deliver.py --node $D/proof/succession-reaffirms-same-target/reaffirm-same-target-succession.md $D 2>&1 | tail -3; python3 -B $P/bin/deliver.py --unrecorded backend $D/implementation/succession-reaffirms-same-target/reaffirm-same-target-succession.md $D/proof/succession-reaffirms-same-target/reaffirm-same-target-succession.md 2>&1 | tail -3
